def _compact_wy(qr: torch.Tensor, tau: torch.Tensor):
    """Convert geqrf's packed panel to Q = I - V T V.T."""
    batch, rows, width = qr.shape
    v = torch.tril(qr, diagonal=-1)
    v = v + torch.eye(rows, width, dtype=qr.dtype, device=qr.device)
    t = torch.zeros((batch, width, width), dtype=qr.dtype, device=qr.device)
    for column in range(width):
        t[:, column, column] = tau[:, column]
        if column:
            overlap = torch.bmm(
                v[:, :, :column].transpose(1, 2),
                v[:, :, column : column + 1],
            )
            coefficient = -tau[:, column, None, None] * overlap
            t[:, :column, column : column + 1] = torch.bmm(
                t[:, :column, :column], coefficient
            )
    return v, t


def _apply_wy_left(
    matrix: torch.Tensor,
    v: torch.Tensor,
    t: torch.Tensor,
    *,
    transpose: bool,
) -> torch.Tensor:
    projected = torch.bmm(v.transpose(1, 2), matrix)
    transform = t.transpose(1, 2) if transpose else t
    projected = torch.bmm(transform, projected)
    return matrix - torch.bmm(v, projected)


def _dense_to_band_eigh(data: torch.Tensor, block: int):
    """Blocked two-sided reduction with compact-WY GEMM updates."""
    n = data.shape[-1]
    band = data.clone()
    reflectors = []

    for panel_start in range(0, n - 2 * block, block):
        tail = panel_start + block
        panel = band[:, tail:, panel_start : panel_start + block].contiguous()
        v, t = _ext.panel_qr_wy(panel)

        band[:, tail:, :] = _apply_wy_left(
            band[:, tail:, :], v, t, transpose=True
        )
        band[:, :, tail:] = _apply_wy_left(
            band[:, :, tail:].transpose(1, 2), v, t, transpose=True
        ).transpose(1, 2)
        reflectors.append((tail, v, t))

    vectors, values, _, _ = _ext.band_eigh(band)
    vectors = vectors.contiguous()
    for tail, v, t in reversed(reflectors):
        vectors[:, tail:, :] = _apply_wy_left(
            vectors[:, tail:, :], v, t, transpose=False
        )
    return vectors, values


def _dense_to_band_xsyev(data: torch.Tensor, block: int):
    """FP32 compact-WY reduction used to stage the n=352 band path."""
    n = data.shape[-1]
    band = data.clone()
    reflectors = []
    previous_precision = torch.get_float32_matmul_precision()
    torch.set_float32_matmul_precision("high")

    for panel_start in range(0, n - 2 * block, block):
        tail = panel_start + block
        panel = band[:, tail:, panel_start : panel_start + block].contiguous()
        v, t = _ext.panel_qr_wy(panel)

        band[:, tail:, :] = _apply_wy_left(
            band[:, tail:, :], v, t, transpose=True
        )
        band[:, :, tail:] = _apply_wy_left(
            band[:, :, tail:].transpose(1, 2), v, t, transpose=True
        ).transpose(1, 2)
        reflectors.append((tail, v, t))

    torch.set_float32_matmul_precision(previous_precision)
    vectors, values, _, _ = _ext.band_eigh(band)
    vectors = vectors.contiguous()
    for tail, v, t in reversed(reflectors):
        vectors[:, tail:, :] = _apply_wy_left(
            vectors[:, tail:, :], v, t, transpose=False
        )
    return vectors, values


def _certify_and_repair(data, vectors, values, refinements=0):
    flags = _ext.certify_eigh(data, vectors, values)
    if not bool(flags[-1]):
        return vectors, values

    unsafe = flags[:-1].bool()
    unsafe_indices = unsafe.nonzero().flatten()
    candidate_data = torch.index_select(data, 0, unsafe_indices)
    candidate_vectors = torch.index_select(vectors, 0, unsafe_indices)

    for refinement in range(refinements):
        candidate_count = candidate_data.shape[0]
        gram = torch.bmm(
            candidate_vectors.transpose(1, 2), candidate_vectors
        )
        correction = gram.mul(-0.5)
        correction.diagonal(dim1=-2, dim2=-1).add_(1.5)
        candidate_vectors = torch.bmm(candidate_vectors, correction)
        aq = torch.bmm(candidate_data, candidate_vectors)
        candidate_values = (candidate_vectors * aq).sum(dim=1)

        refined_flags = _ext.certify_eigh(
            candidate_data, candidate_vectors, candidate_values
        )
        still_unsafe = refined_flags[:-1].bool()
        now_safe = ~still_unsafe
        remaining_count = int(still_unsafe.sum())
        if remaining_count < candidate_count:
            safe_positions = now_safe.nonzero().flatten()
            safe_indices = torch.index_select(
                unsafe_indices, 0, safe_positions
            )
            vectors[safe_indices] = torch.index_select(
                candidate_vectors, 0, safe_positions
            )
            values[safe_indices] = torch.index_select(
                candidate_values, 0, safe_positions
            )
        if remaining_count == 0:
            return vectors, values
        remaining_positions = still_unsafe.nonzero().flatten()
        unsafe_indices = torch.index_select(
            unsafe_indices, 0, remaining_positions
        )
        candidate_data = torch.index_select(
            candidate_data, 0, remaining_positions
        )
        candidate_vectors = torch.index_select(
            candidate_vectors, 0, remaining_positions
        )
        if (refinement + 1 < refinements and
                remaining_count * 4 > candidate_count):
            break

    repaired_vectors, repaired_values = _ext.xsyev_batched(candidate_data)
    vectors[unsafe_indices] = repaired_vectors
    values[unsafe_indices] = repaired_values
    return vectors, values


def _blocked_wy_backtransform(vectors, reflectors, taus, block):
    n = vectors.shape[-1]
    previous_precision = torch.get_float32_matmul_precision()
    torch.set_float32_matmul_precision("highest")
    for start in reversed(range(0, n - 2, block)):
        width = min(block, n - 2 - start)
        tail = start + 1
        panel = reflectors[:, tail:, start : start + width]
        v = torch.tril(panel, diagonal=-1)
        v = v + torch.eye(
            v.shape[1], width, dtype=v.dtype, device=v.device
        )
        gram = torch.bmm(v.transpose(1, 2), v)
        t = _ext.compact_wy_t(
            gram, taus[:, start : start + width].contiguous()
        )
        vectors[:, tail:, :] = _apply_wy_left(
            vectors[:, tail:, :], v, t, transpose=False
        )
    torch.set_float32_matmul_precision(previous_precision)
    return vectors


def _custom_eigh512(data):
    vectors, values, reflectors, taus = _ext.band_eigh(data)
    vectors = _blocked_wy_backtransform(
        vectors, reflectors, taus, 128
    )
    return _certify_and_repair(data, vectors, values, refinements=2)


def _eigh512(data):
    diagonal = data.diagonal(dim1=-2, dim2=-1)
    trace = diagonal.sum(dim=-1)
    diagonal_norm = torch.linalg.vector_norm(diagonal, dim=-1)
    library_mask = trace > 21.5 * diagonal_norm
    library_count = int(library_mask.sum())
    if library_count == 0:
        return _custom_eigh512(data)
    if library_count == data.shape[0]:
        return _ext.xsyev_batched(data)

    custom_mask = ~library_mask
    custom_vectors, custom_values = _custom_eigh512(
        data[custom_mask].contiguous()
    )
    library_vectors, library_values = _ext.xsyev_batched(
        data[library_mask].contiguous()
    )
    vectors = torch.empty_like(data)
    values = torch.empty(
        data.shape[:2], dtype=data.dtype, device=data.device
    )
    vectors[custom_mask] = custom_vectors
    values[custom_mask] = custom_values
    vectors[library_mask] = library_vectors
    values[library_mask] = library_values
    return vectors, values


def custom_kernel(data: input_t) -> output_t:
    if data.shape[-1] == 32:
        vectors, values = _ext.jacobi32(data)
    elif data.shape[-1] == 176:
        vectors, values = _dense_to_band_eigh(data, 88)
        vectors, values = _certify_and_repair(data, vectors, values)
    elif data.shape[-1] == 352:
        vectors, values = _dense_to_band_xsyev(data, 128)
        vectors, values = _certify_and_repair(data, vectors, values)
    elif data.shape[-1] == 512:
        vectors, values = _eigh512(data)
    else:
        vectors, values = _ext.xsyev_batched(data)
    return vectors, values

